(()=>{const e=[...document.querySelectorAll("[data-count]")];if(!e.length||!("IntersectionObserver"in window))return;if(matchMedia("(prefers-reduced-motion: reduce)").matches)return;const n=e=>{const t=Number(e.dataset.count);if(!Number.isFinite(t)||t<2)return;const s=900,o=performance.now(),n=i=>{const a=Math.max(0,Math.min(1,(i-o)/s)),r=1-(1-a)**4;e.textContent=String(Math.round(t*r)),a<1&&requestAnimationFrame(n)};requestAnimationFrame(n)},t=new IntersectionObserver(e=>{for(const s of e){if(!s.isIntersecting)continue;t.unobserve(s.target),n(s.target)}},{threshold:.6});e.forEach(e=>t.observe(e))})()